//--------------------------------------------------------------------------//
//! \desc  Use this method to link a Reg_Func with an id key
//!        

//! \assume Reg_Table is a valid pointer

//! \notes  Public method

//! \param  reg       the Reg_Table object
//! \param  id        the Reg_Id key linked with Reg_Func 

//! \return -none-
//--------------------------------------------------------------------------//

void  reg_func( Reg_Table reg  , Reg_Id id , Reg_Func func  )
{
    Reg_Table_Id table_id = NULL ;
    
    if( reg_atomic_request( reg ) )
    {                
        table_id = reg_check_id( reg , id );

        if( table_id == NULL )
        {
            table_id = reg_create_id( reg , id );
        }

        if( table_id != NULL )
        {
            Reg_Obj_Without_Data new_obj = (Reg_Obj_Without_Data)os_mem_request( sizeof( struct s_Reg_Obj_Without_Data ) );

            if( new_obj )
            {
                new_obj->func = func ;
                new_obj->next = table_id->next_reg_obj ;

                table_id->next_reg_obj = new_obj ;
            }
        }

        reg_atomic_release( reg );
    }                
}

